# Closure Example
def make_multiplier(x):
    def multiply(n):
        return x * n
    return multiply

double = make_multiplier(2)
print(double(5))  # Output: 10

# Decorator Example
def my_decorator(func):
    def wrapper():
        print("Before function call")
        func()
        print("After function call")
    return wrapper

@my_decorator
def say_hello():
    print("Hello!")

